public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();

    // Base case: if the input array has only one element,
    // return a list containing only one list with that element
    if (nums.length == 1) {
        permutations.add(Collections.singletonList(nums[0]));
        return permutations;
    }

    // Recursive case: for each permutation of the input array,
    // construct all permutations of the remaining elements
    for (int i = 0; i < nums.length; i++) {
        // Create a new list to store the permutations of the remaining elements
        List<List<Integer>> remainingPermutations = new ArrayList<>();

        // Generate all permutations of the remaining elements
        for (int j = 0; j < nums.length - 1; j++) {
            // If the current element is not equal to the element at index i,
            // add it to the list of remaining elements
            if (j != i) {
                remainingPermutations.add(Collections.singletonList(nums[j]));
            }
        }

        // Add all permutations of the remaining elements to the output list
        for (List<Integer> permutation : remainingPermutations) {
            permutation.add(0, nums[i]);
            permutations.add(permutation);
        }
    }

    return permutations;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 0) {
        return result;
    }

    permute(nums, 0, result);

    return result;
}

private void permute(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        List<Integer> permutation = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            permutation.add(nums[i]);
        }
        result.add(permutation);
        return;
    }

    for (int i = start; i < nums.length; i++) {
        int tmp = nums[i];
        nums[i] = nums[start];
        nums[start] = tmp;
        permute(nums, start + 1, result);
        tmp = nums[i];
        nums[i] = nums[start];
        nums[start] = tmp;
    }
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
        List<Integer> list = new ArrayList<>();
        list.add(nums[0]);
        result.add(list);
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int[] newNums = new int[nums.length - 1];
        System.arraycopy(nums, 0, newNums, 0, i);
        System.arraycopy(nums, i + 1, newNums, i, nums.length - i - 1);
        List<List<Integer>> perm = permute(newNums);
        for (List<Integer> p : perm) {
            p.add(0, nums[i]);
            result.add(p);
        }
    }
    return result;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 0) {
        return result;
    } else if (nums.length == 1) {
        result.add(Arrays.asList(nums[0]));
        return result;
    }

    for (int i = 0; i < nums.length; i++) {
        int[] remainingNums = Arrays.copyOfRange(nums, 0, nums.length);
        remainingNums[i] = 0;
        int[] nextNums = Arrays.copyOfRange(remainingNums, 0, nums.length - 1);

        List<List<Integer>> smallerPermutations = permute(nextNums);
        for (List<Integer> smallerPermutation : smallerPermutations) {
            smallerPermutation.add(nums[i]);
            result.add(smallerPermutation);
        }
    }

    return result;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    backtrack(nums, 0, result);
    return result;
}

private void backtrack(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        result.add(Arrays.stream(nums).boxed().collect(Collectors.toList()));
    } else {
        for (int i = start; i < nums.length; i++) {
            swap(nums, start, i);
            backtrack(nums, start + 1, result);
            swap(nums, start, i);
        }
    }
}

private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

