public int findLargestSubstring(List<String> strings) {
    // Initialize the largest substring size and its inverse
    int largestSubstringSize = -1;
    int largestSubstringInverseSize = -1;
    // Loop through each string in the list
    for (String string : strings) {
        // Get the size of the current string
        int stringSize = string.length();
        // Loop through each character in the string
        for (int i = 0; i < stringSize; i++) {
            // Get the current character
            char currentChar = string.charAt(i);
            // Check if the current character is a substring of any other string
            boolean isSubstring = false;
            // Loop through each other string
            for (String otherString : strings) {
                // Check if the other string contains the current character
                if (otherString.contains(currentChar)) {
                    isSubstring = true;
                    break;
                }
            }
            // If the current character is a substring, check if it's the largest substring
            if (isSubstring) {
                // Check if the current character is the inverse of another character
                for (char otherChar : string.toCharArray()) {
                    if (otherChar != currentChar) {
                        if (string.contains(otherChar)) {
                            if (!isSubstring && otherChar < currentChar) {
                                isSubstring = true;
                            }
                        }
                    }
                }
                // If the current character is the largest substring, set its size
                if (isSubstring) {
                    largestSubstringSize = stringSize;
                }
            }
        }
    }
    // If no substrings were found, return -1
    if (largestSubstringSize == -1) {
        return -1;
    }
    // Return the largest substring size
    return largestSubstringSize;
}

public static int countOilDeposits(char[][] grid) {

    // Calculate the number of columns in the grid
    int nCols = grid[0].length;

    // Initialize a 2D array to keep track of visited cells
    boolean[][] visited = new boolean[grid.length][nCols];

    // Initialize the number of distinct oil deposits to 0
    int numOilDeposits = 0;

    // Iterate over each row in the grid
    for (int i = 0; i < grid.length; i++) {
      // Iterate over each column in the grid
      for (int j = 0; j < nCols; j++) {
        // If the current cell is an oil deposit and we haven't visited it before,
        // increment the number of oil deposits and mark the cell as visited
        if (grid[i][j] == '@' && !visited[i][j]) {
          numOilDeposits++;
          visited[i][j] = true;

          // Recursively search all connected oil deposits
          countOilDeposits(grid, i, j, visited);
        }
      }
    }

    return numOilDeposits;
  }

private static void countOilDeposits(char[][] grid, int row, int col, boolean[][] visited) {

    // If the current cell is an oil deposit and we haven't visited it before,
    // mark the cell as visited and increment the number of oil deposits
    if (grid[row][col] == '@' && !visited[row][col]) {
      visited[row][col] = true;
    }

    // Check if the cell is on the edge of the grid,
    // return if we are at the edge
    if (row == 0 || row == grid.length - 1 || col == 0 || col == grid[0].length - 1) return;

    // Check if the cell to the left is an oil deposit and has not been visited
    if (grid[row][col - 1] == '@' && !visited[row][col - 1]) {
      countOilDeposits(grid, row, col - 1, visited);
    }

    // Check if the cell to the right is an oil deposit and has not been visited
    if (grid[row][col + 1] == '@' && !visited[row][col + 1]) {
      countOilDeposits(grid, row, col + 1, visited);
    }

    // Check if the cell above is an oil deposit and has not been visited
    if (grid[row - 1][col] == '@' && !visited[row - 1][col]) {
      countOilDeposits(grid, row - 1, col, visited);
    }

    // Check if the cell below is an oil deposit and has not been visited
    if (grid[row + 1][col] == '@' && !visited[row + 1][col]) {
      countOilDeposits(grid, row + 1, col, visited);
    }
  }

public static int countOilDeposits(char[][] grid) {
    int numDeposits = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                // Check if the current location is part of an oil deposit
                // by looking at the surrounding 8 locations
                boolean isDeposit = false;
                for (int k = -1; k <= 1; k++) {
                    for (int l = -1; l <= 1; l++) {
                        if (i + k >= 0 && i + k < grid.length && j + l >= 0 && j + l < grid[i].length) {
                            if (grid[i + k][j + l] == '@') {
                                isDeposit = true;
                                break;
                            }
                        }
                    }
                    if (isDeposit) {
                        break;
                    }
                }
                if (isDeposit) {
                    numDeposits++;
                }
            }
        }
    }
    return numDeposits;
}

