private static void markCellsAsVisited(char[][] grid, int i, int j) {
    // Make sure the current cell is not a wall (i.e., it is not '*')
    if (grid[i][j] != '*') {
        // Mark the current cell as visited
        grid[i][j] = '@';
        // Search for nearby oil pits
        for (int x = i - 1; x <= i + 1; x++) {
            for (int y = j - 1; y <= j + 1; y++) {
                // Make sure the current cell is within the bounds of the grid
                if (x >= 0 && x < grid.length && y >= 0 && y < grid[i].length) {
                    if (grid[x][y] == '@') {
                        // If the current cell is an oil pit, mark it as visited and search for nearby oil pits
                        markCellsAsVisited(grid, x, y);
                    }
                }
            }
        }
    }
}

