public static void floodFill(char[][] grid, int i, int j, char from, char to) {
    if (grid[i][j] != from) {
        return;
    }
    grid[i][j] = to;
    floodFill(grid, i - 1, j, from, to);
    floodFill(grid, i + 1, j, from, to);
    floodFill(grid, i, j - 1, from, to);
    floodFill(grid, i, j + 1, from, to);
}

