public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Variables to keep track of visited n-tersections and current path length
    boolean[] visited = new boolean[n];
    int pathLength = 0;

    // Initially mark the starting n-tersection as visited
    visited[start[0]][start[1]] = true;

    // Recursively search for a path from the starting n-tersection to the ending n-tersection
    String result = canTravelMazeHelper(n, start, end, paths, visited, pathLength);

    // If a path was found, return "can be travelled"
    if (result != null) {
        return "can be travelled";
    }

    // Otherwise, return "cannot be travelled"
    return "cannot be travelled";
}

private static String canTravelMazeHelper(int n, int[] start, int[] end, int[][] paths, boolean[][] visited, int pathLength) {
    // If the current n-tersection is the ending n-tersection, return a path length of 0
    if (start[0] == end[0] && start[1] == end[1]) {
        return Integer.toString(pathLength);
    }

    // Otherwise, recursively search for a path from all adjacent n-tersections
    for (int[] path : paths) {
        // Check if the current n-tersection is adjacent to the ending n-tersection
        if (path[0] == start[0] && path[1] == start[1]) {
            // Calculate the new path length and check if it is within the allowed range
            int newPathLength = pathLength + path[2];
            if (newPathLength > 0 && newPathLength <= n) {
                // Recursively search for a path from the adjacent n-tersection to the ending n-tersection
                String result = canTravelMazeHelper(n, path, end, paths, visited, newPathLength);

                // If a path was found, return it
                if (result != null) {
                    return result;
                }
            }
        }
    }

    // A path could not be found, return null
    return null;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending n-tersections are invalid
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n) {
        return "cannot be travelled";
    }
    if (end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Check if the n-teresting space is valid
    if (paths.length != n || paths[0].length != n) {
        return "cannot be travelled";
    }

    // Initialize a visited matrix to keep track of the n-tersections that have been visited
    boolean[][] visited = new boolean[n][n];

    // Initialize a queue to store the next n-tersections to visit
    Queue<int[]> queue = new LinkedList<>();

    // Add the starting n-tersection to the queue
    queue.offer(start);

    // Mark the starting n-tersection as visited
    visited[start[0]][start[1]] = true;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the next n-tersection to visit
        int[] current = queue.poll();

        // Check if the current n-tersection is the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Check if the current n-tersection has been visited before
        if (visited[current[0]][current[1]]) {
            continue;
        }

        // Mark the current n-tersection as visited
        visited[current[0]][current[1]] = true;

        // Get the paths from the current n-tersection
        int[][] currentPaths = paths[current[0]][current[1]];

        // Loop through each path
        for (int[] path : currentPaths) {
            // Check if the path is valid
            if (path[0] < 0 || path[0] >= n || path[1] < 0 || path[1] >= n || visited[path[0]][path[1]]) {
                continue;
            }

            // Add the path to the queue
            queue.offer(path);
        }
    }

    // If the queue is empty, it means that the ending n-tersection cannot be reached
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a queue to store the path
    Queue<int[]> queue = new LinkedList<>();

    // Add the starting coordinates to the queue
    queue.add(start);

    // Declare a visited set to keep track of visited n-tersections
    Set<int[]> visited = new HashSet<>();

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current coordinates from the queue
        int[] current = queue.poll();

        // If the current coordinates match the ending coordinates, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // If the current coordinates have not been visited, mark them as visited and add their neighbors to the queue
        if (!visited.contains(current)) {
            visited.add(current);

            // Get the neighbors of the current coordinates
            List<int[]> neighbors = getNeighbors(n, current, paths);

            // Add the neighbors to the queue
            queue.addAll(neighbors);
        }
    }

    // If the ending coordinates were not found in the queue, return "cannot be travelled"
    return "cannot be travelled";
}

private static List<int[]> getNeighbors(int n, int[] coordinates, int[][] paths) {
    // Initialize a list to store the neighbors
    List<int[]> neighbors = new ArrayList<>();

    // Loop through each path in the paths
    for (int[] path : paths) {
        // If the coordinates of the path match the current coordinates, add the neighbor coordinates to the list
        if (Arrays.equals(coordinates, path)) {
            neighbors.add(path);
        }
    }

    // Return the list of neighbors
    return neighbors;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean flag to keep track of whether travel is possible
    boolean travelPossible = true;

    // Check if the starting and ending n-tersections are not equal
    if (start[0] == end[0] && start[1] == end[1]) {
        // If they are equal, return "cannot be travelled"
        travelPossible = false;
    }

    // Loop through all the n-tersections
    for (int i = 0; i < n; i++) {
        // If the n-tersection coordinate is equal to the starting n-tersection coordinate, break out of the loop
        if (i == start[0] && start[1] == i) {
            break;
        }

        // If the n-tersection coordinate is not a part of the path between the starting and ending coordinates, set the travel possible flag to false
        if (!pathContainsCoordinate(i, paths)) {
            travelPossible = false;
            break;
        }
    }

    // Return "can be travelled" if the travel is possible, otherwise return "cannot be travelled"
    return travelPossible ? "can be travelled" : "cannot be travelled";
}

private static boolean pathContainsCoordinate(int n, int[][] paths) {
    // Loop through all the paths
    for (int[] path : paths) {
        // If the n-tersection coordinate is a part of the path, return true
        if (path[0] == n || path[1] == n) {
            return true;
        }
    }

    // If the n-tersection coordinate is not part of any path, return false
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Check if starting and ending n-tersection coordinates are valid
  if (!isValidCoordinate(start, n) || !isValidCoordinate(end, n)) {
    return "invalild input";
  }

  // Check if paths are valid
  for (int i = 0; i < paths.length; i++) {
    if (isInvalidPath(paths[i])) {
      return "invalid path";
    }
  }

  // Check if the maze is solvable using BFS or DFS
  if (isSolvable(start, end, paths)) {
    return "can be travelled";
  }

  return "cannot be travelled";
}

