    int weekday = Integer.parseInt(dateComponents[2] + dateComponents[1] + dateComponents[0]);

    // use the formula to find the weekday of the date
    int m = monthValue;
    int s = 2000;
    int century = 6 * (year/100) + 4 * (year % 100) + 5 * m + 3 * (day + 1) + (year % 100) / 4 + 53 * s / 100 + (century/4);
    int remainder = s % 100;
    int d = (century + remainder - 6 * (century/4)) % 7;
    String weekdayString = "${month} $day, ${year} is a ${weekdayMap.get(d)}";

    return weekdayString;
}

