    Arrays.sort(chars);
    StringBuilder result = new StringBuilder();
    int length = chars.length;
    int i = 0;
    while (i < length) {
        appendSmallestChar(chars, length, result);
        appendSmallestGreaterChar(chars, length, result);
        appendLargestChar(chars, length, result);
        appendLargestSmallerChar(chars, length, result);
        i++;
    }
    return result.toString();
}

private void appendSmallestChar(char[] chars, int length, StringBuilder result) {
    char smallest = chars[0];
    int smallestIndex = 0;
    for (int i = 1; i < length; i++) {
        if (chars[i] < smallest) {
            smallest = chars[i];
            smallestIndex = i;
        }
    }
    result.append(smallest);
    for (int i = smallestIndex; i < length - 1; i++) {
        chars[i] = chars[i + 1];
    }
    chars[length - 1] = 0;
}

private void appendSmallestGreaterChar(char[] chars, int length, StringBuilder result) {
    char smallestGreater = chars[0];
    int smallestGreaterIndex = 0;
    for (int i = 1; i < length; i++) {
        if (chars[i] > smallestGreater && chars[i] < result.charAt(result.length() - 1)) {
            smallestGreater = chars[i];
            smallestGreaterIndex = i;
        }
    }
    result.append(smallestGreater);
    for (int i = smallestGreaterIndex; i < length - 1; i++) {
        chars[i] = chars[i + 1];
    }
    chars[length - 1] = 0;
}

private void appendLargestChar(char[] chars, int length, StringBuilder result) {
    char largest = chars[length - 1];
    int largestIndex = length - 1;
    for (int i = length - 2; i >= 0; i--) {
        if (chars[i] > largest) {
            largest = chars[i];
            largestIndex = i;
        }
    }
    result.append(largest);
    for (int i = largestIndex; i > 0; i--) {
        chars[i] = chars[i - 1];
    }
    chars[0] = 0;
}

private void appendLargestSmallerChar(char[] chars, int length, StringBuilder result) {
    char largestSmaller = chars[length - 1];
    int largestSmallerIndex = length - 1;
    for (int i = length - 2; i >= 0; i--) {
        if (chars[i] < largestSmaller && chars[i] > result.charAt(result.length() - 1)) {
            largestSmaller = chars[i];
            largestSmallerIndex = i;
        }
    }
    result.append(largestSmaller);
    for (int i = largestSmallerIndex; i > 0; i--) {
        chars[i] = chars[i - 1];
    }
    chars[0] = 0;
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    while (s.length() > 0) {
        // Pick the smallest character from s and append it to the result
        int minIndex = 0;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < s.charAt(minIndex)) {
                minIndex = i;
            }
        }
        result.append(s.charAt(minIndex));
        s = s.substring(0, minIndex) + s.substring(minIndex + 1);

        // Pick the smallest character from s which is greater than the last appended character to the result and append it
        int nextMinIndex = 0;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) > s.charAt(nextMinIndex) && s.charAt(i) > s.charAt(minIndex)) {
                nextMinIndex = i;
            }
        }
        if (nextMinIndex != 0) {
            result.append(s.charAt(nextMinIndex));
            s = s.substring(0, nextMinIndex) + s.substring(nextMinIndex + 1);
        }

        // Pick the largest character from s and append it to the result
        int maxIndex = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) > s.charAt(maxIndex)) {
                maxIndex = i;
            }
        }
        result.append(s.charAt(maxIndex));
        s = s.substring(0, maxIndex) + s.substring(maxIndex + 1);

        // Pick the largest character from s which is smaller than the last appended character to the result and append it
        int nextMaxIndex = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) < s.charAt(nextMaxIndex) && s.charAt(i) < s.charAt(maxIndex)) {
                nextMaxIndex = i;
            }
        }
        if (nextMaxIndex != 0) {
            result.append(s.charAt(nextMaxIndex));
            s = s.substring(0, nextMaxIndex) + s.substring(nextMaxIndex + 1);
        }
    }
    return result.toString();
}

