public String sortString(String s) {
    // Convert the input string to a character array for easy manipulation
    char[] chars = s.toCharArray();

    // Sort the character array in ascending order using a custom comparator
    Arrays.sort(chars, new Comparator<Character>() {
        @Override
        public int compare(Character o1, Character o2) {
            return o1.compareTo(o2);
        }
    });

    // Iterate through the sorted character array and append the characters to a result string in the required order
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < chars.length) {
        // Append the smallest character
        result.append(chars[i]);

        // Find the smallest character that is greater than the last appended character
        int smallestGreater = 0;
        for (int j = i + 1; j < chars.length; j++) {
            if (chars[j] > chars[i]) {
                smallestGreater = j;
                break;
            }
        }

        // Append the smallest character that is greater than the last appended character
        if (smallestGreater != 0) {
            result.append(chars[smallestGreater]);
            i = smallestGreater;
        }

        // Find the largest character
        int largest = 0;
        for (int j = chars.length - 1; j >= i; j--) {
            if (chars[j] > chars[i]) {
                largest = j;
                break;
            }
        }

        // Append the largest character
        result.append(chars[largest]);

        // Find the largest character that is smaller than the last appended character
        int largestSmaller = 0;
        for (int j = i + 1; j < largest; j++) {
            if (chars[j] < chars[i]) {
                largestSmaller = j;
                break;
            }
        }

        // Append the largest character that is smaller than the last appended character
        if (largestSmaller != 0) {
            result.append(chars[largestSmaller]);
        }

        // Increment the counter to move to the next character
        i++;
    }

    // Return the result string
    return result.toString();
}

