public boolean splitArraySameAverage(int[] nums) {
    int average = 0;
    for (int num : nums) {
        average += num;
    }
    average /= nums.length;

    // Check if the array can be split into two non-empty arrays with the same average
    for (int i = 0; i < nums.length - 1; i++) {
        int leftSum = 0, rightSum = 0;
        for (int j = 0; j <= i; j++) {
            leftSum += nums[j];
        }
        for (int j = i + 1; j < nums.length; j++) {
            rightSum += nums[j];
        }
        if (leftSum / (i + 1) == rightSum / (nums.length - i - 1) && average == (leftSum + rightSum) / nums.length) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
