        sum += nums[i];
    }
    int n = nums.length / 2;
    if (nums.length % 2 != 0) {
        n++;
    }
    double avg = sum / (nums.length * 1.0);
    int[] left = Arrays.copyOf(nums, n);
    int[] right = Arrays.copyOfRange(nums, n, nums.length);
    return left.length > 0 && right.length > 0 && (sumOfArray(left) / left.length == sumOfArray(right) / right.length);
}

