public boolean splitArraySameAverage(int[] nums) {
    // Calculate the sum of the entire array
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // Calculate the average of the entire array
    double avg = sum / (double) nums.length;

    // Split the array into two sub-arrays
    int[] subArray1 = new int[nums.length / 2];
    int[] subArray2 = new int[nums.length - subArray1.length];
    for (int i = 0; i < subArray1.length; i++) {
        subArray1[i] = nums[i];
    }
    for (int i = subArray1.length; i < nums.length; i++) {
        subArray2[i - subArray1.length] = nums[i];
    }

    // Calculate the sum of the sub-arrays
    int subArray1Sum = 0;
    int subArray2Sum = 0;
    for (int num : subArray1) {
        subArray1Sum += num;
    }
    for (int num : subArray2) {
        subArray2Sum += num;
    }

    // Calculate the average of the sub-arrays
    double subArray1Avg = subArray1Sum / (double) subArray1.length;
    double subArray2Avg = subArray2Sum / (double) subArray2.length;

    // Check if the averages of the sub-arrays are equal
    return subArray1Avg == subArray2Avg;
}

