    double lhs = 0;
    int count = 0;
    for (int i = 0; i < nums.length; i++) {
        if (nums[i] <= avg) {
            lhs += nums[i];
            count++;
        }
    }
    if (count == 0 || count == nums.length) {
        return false;
    }
    double rhs = total - lhs;
    return (lhs / count) == (rhs / (nums.length - count));
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = 0;
    int minCostIndex0 = cost[0];
    int minCostIndex1 = cost[1];
    for (int i = 2; i < cost.length; i++) {
        minCost = Math.min(minCostIndex0 + cost[i], minCostIndex1 + cost[i - 1]);
        minCostIndex0 = minCostIndex1;
        minCostIndex1 = minCost;
    }
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int minCost1 = cost[0] + minCostClimbingStairs(cost, 1);
    int minCost2 = cost[1] + minCostClimbingStairs(cost, 2);
    return Math.min(minCost1, minCost2);
}

private int minCostClimbingStairs(int[] cost, int startIndex) {
    if (startIndex == cost.length - 1) {
        return 0;
    } else {
        return Math.min(cost[startIndex] + minCostClimbingStairs(cost, startIndex + 1),
                        cost[startIndex + 1] + minCostClimbingStairs(cost, startIndex + 2));
    }
}

public int minCostClimbingStairs(int[] cost) {
    if (cost.length == 0) {
        return 0;
    } else if (cost.length == 1) {
        return cost[0];
    } else if (cost.length == 2) {
        return Math.min(cost[0], cost[1]);
    }

    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }

    return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) {
        return 0;
    } else if (n == 1) {
        return cost[0];
    } else if (n == 2) {
        return Math.min(cost[0], cost[1]);
    }

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    dp[2] = Math.min(cost[0], cost[1]);

    for (int i = 3; i < n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i], dp[i - 2] + cost[i]);
    }

    return dp[n - 1];
}

public int minCostClimbingStairs(int[] cost) {
    int start1 = cost[0];
    int start2 = cost[1];
    int[] memo = new int[cost.length];
    memo[0] = start1;
    memo[1] = start2;
    for (int i = 2; i < cost.length; i++) {
        memo[i] = Math.min(memo[i - 1] + cost[i], memo[i - 2] + cost[i - 1]);
    }
    return Math.min(memo[cost.length - 1], memo[cost.length - 2]);
}

