public boolean hasAllCodes(String s, int k) {
    // Check if k is a valid substring length
    if (k < 1 || k > s.length()) {
        throw new IllegalArgumentException("Invalid substring length k");
    }

    // Initialize a set to store all substrings of length k
    Set<String> substrings = new HashSet<>();

    // Iterate over the string and add all substrings of length k to the set
    for (int i = 0; i <= s.length() - k; i++) {
        substrings.add(s.substring(i, i + k));
    }

    // Check if the set contains all possible substrings of length k
    for (int i = 0; i < (1 << k); i++) {
        String substring = Integer.toBinaryString(i);
        while (substring.length() < k) {
            substring = "0" + substring;
        }
        if (!substrings.contains(substring)) {
            return false;
        }
    }

    // If the set contains all possible substrings, return true
    return true;
}

public boolean hasAllCodes(String s, int k) {
    // Check if s is a valid binary string
    if (s == null || s.isEmpty() || s.length() < k) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Check if k is a valid length
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }

    // Check if every binary string of length k is a substring of s
    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        if (!isBinaryString(substring)) {
            return false;
        }
    }

    return true;
}

