public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        throw new IllegalArgumentException("n and k should be positive integers.");
    }
    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            if (++count == k) {
                return i;
            }
        }
    }
    return -1;
}

