public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    int[] factors = new int[k];
    int i = 0;
    for (int factor = 1; factor < Math.sqrt(n); factor++) {
        if (n % factor == 0) {
            if (i < k) {
                factors[i] = factor;
                i++;
            }
            if (i < k && n / factor != factor) {
                factors[i] = n / factor;
                i++;
            }
        }
    }
    if (i < k) {
        factors = Arrays.copyOfRange(factors, 0, i);
    }
    return factors[k - 1];
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        throw new IllegalArgumentException("n and k should be positive integers.");
    }
    List<Integer> factors = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
        }
    }
    if (factors.size() < k) {
        return -1;
    }
    Collections.sort(factors);
    return factors.get(k - 1);
}

public static String makeGood(String s) {
    char[] charArray = s.toCharArray();
    boolean shouldRepeat = false;
    for (int i = 0; i < charArray.length - 1; i++) {
        char currentChar = charArray[i];
        char nextChar = charArray[i + 1];
        if (currentChar == Character.toLowerCase(nextChar)) {
            shouldRepeat = true;
            charArray[i + 1] = '\0';
        } else if (currentChar == Character.toUpperCase(nextChar)) {
            shouldRepeat = true;
            charArray[i] = '\0';
        }
    }
    if (shouldRepeat) {
        return makeGood(new String(charArray));
    } else {
        return new String(charArray);
    }
}

