private static boolean isSteppingNumber(int num) {
    // If the number is less than or equal to 0, it is not a stepping number
    if (num <= 0) {
        return false;
    }

    // Iterate through each digit in the number
    while (num > 0) {
        // If the current digit is not one more or one less than the adjacent digit, the number is not a stepping number
        if (!(num % 10 == 9 || num % 10 == 8 || num % 10 == 4 || num % 10 == 3 || num % 10 == 6 || num % 10 == 1)) {
            return false;
        }
        num /= 10;
    }

    // The number is a stepping number
    return true;
}

