private static boolean isSteppingNumber(int num) {
    //Step 1: check if the number has more than one digit
    if (num < 10) {
        return false;
    }

    //Step 2: check if each digit is either one more or one less than the adjacent digit
    int previousDigit = num % 10;
    num /= 10;
    while (num >= 10) {
        int currentDigit = num % 10;
        if (currentDigit != previousDigit + 1 && currentDigit != previousDigit - 1) {
            return false;
        }
        previousDigit = currentDigit;
        num /= 10;
    }

    //Step 3: the number is a stepping number if it passes the checks
    return true;
}

