public static int longestLine(int[][] mat) {
    int m = mat.length, n = mat[0].length;
    int maxLength = 0, currentLength = 0;

    // Initialize a 2D array to keep track of the longest line in each direction
    int[][] longestLineInDirection = new int[2][n];

    // Iterate over each cell in the matrix and check if it is part of a longer line
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Check if the current cell is part of a longer line in each direction
                currentLength = 1;
                for (int k = 1; k < maxLength; k++) {
                    if (j + k < n && mat[i][j + k] == 1) {
                        currentLength++;
                    } else {
                        break;
                    }
                }
                longestLineInDirection[0][j] = Math.max(longestLineInDirection[0][j], currentLength);
                currentLength = 1;
                for (int k = 1; k < maxLength; k++) {
                    if (i + k < m && mat[i + k][j] == 1) {
                        currentLength++;
                    } else {
                        break;
                    }
                }
                longestLineInDirection[1][j] = Math.max(longestLineInDirection[1][j], currentLength);
            }
        }
    }

    // Find the maximum length of a line in any direction
    for (int i = 0; i < n; i++) {
        maxLength = Math.max(maxLength, Math.max(longestLineInDirection[0][i], longestLineInDirection[1][i]));
    }

    return maxLength;
}

