private static int findMaxLen(int[][] mat, int i, int j, int len, int dir) {
    if (i < 0 || i >= mat.length || j < 0 || j >= mat[0].length || mat[i][j] != 1) {
        return len;
    }

    len++;
    mat[i][j] = 0;

    if (dir == 0) {
        len = Math.max(len, findMaxLen(mat, i, j-1, len, 0));
        len = Math.max(len, findMaxLen(mat, i, j+1, len, 0));
        len = Math.max(len, findMaxLen(mat, i-1, j, len, 1));
        len = Math.max(len, findMaxLen(mat, i+1, j, len, 1));
    } else if (dir == 1) {
        len = Math.max(len, findMaxLen(mat, i-1, j, len, 2));
        len = Math.max(len, findMaxLen(mat, i+1, j, len, 2));
        len = Math.max(len, findMaxLen(mat, i, j-1, len, 3));
        len = Math.max(len, findMaxLen(mat, i, j+1, len, 3));
    } else if (dir == 2) {
        len = Math.max(len, findMaxLen(mat, i-1, j-1, len, 0));
        len = Math.max(len, findMaxLen(mat, i+1, j+1, len, 0));
        len = Math.max(len, findMaxLen(mat, i-1, j+1, len, 1));
        len = Math.max(len, findMaxLen(mat, i+1, j-1, len, 1));
    } else {
        len = Math.max(len, findMaxLen(mat, i-1, j-1, len, 2));
        len = Math.max(len, findMaxLen(mat, i+1, j+1, len, 2));
        len = Math.max(len, findMaxLen(mat, i-1, j+1, len, 3));
        len = Math.max(len, findMaxLen(mat, i+1, j-1, len, 3));
    }

    return len;
}

