public static string addThousandSeparator(int n) {

  if (n < 0) {
    throw new IllegalArgumentException("n cannot be negative");
  }

  var nStr = n.ToString();
  var dotIndex = nStr.Length() % 3 == 0 ? nStr.Length() - 3 : nStr.Length() % 3;

  var builder = new StringBuilder();
  builder.Append(nStr);

  do {
    builder.Insert(dotIndex, '.');
    dotIndex -= 3;
  } while (dotIndex >= 0);

  return builder.ToString();
}

public static String addThousandSeparator(int n) {
    // Split the integer into individual digits
    String digits = String.valueOf(n);
    String result = "";

    // Add a dot every three digits starting from the right side
    for (int i = digits.length() - 1; i >= 0; i -= 3) {
        result = digits.substring(i, i + 3) + (i > 0 ? "." : "") + result;
    }

    // Return the result as a string
    return result.substring(0, result.length() - 1);
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    if (n < 0) {
        return "-" + addThousandSeparator(-n);
    }

    var str = n.ToString();
    var separators = str.Length % 3 == 0 ? str.Length / 3 : (str.Length + 2) / 3;

    var result = "";
    for (var i = 0; i < separators; i++) {
        var chunk = str.Substring(i * 3, 3);
        result += chunk + (separators - 1 == i ? "" : ".");
    }

    return result;
}

public static String addThousandSeparator(int n) {
    String result = String.valueOf(n);
    int length = result.length();
    if (length <= 3) {
        return result;
    }
    int start = length - 3;
    while (start > 0) {
        int end = start - 3;
        result = result.substring(0, end) + "." + result.substring(end, start);
        start = end;
    }
    return result.substring(0, start) + "." + result.substring(start);
}

