public static int[] diagonalOrder(int[][] mat) {
    // Initialize an array to store the diagonal order
    int[] diagonal = new int[mat.length * mat[0].length];
    // Loop variables
    int i = 0; // row index
    int j = 0; // column index
    int k = 0; // array index

    // Loop through each element in the matrix
    while (i < mat.length && j < mat[0].length) {
        // Add the current element to the diagonal array
        diagonal[k++] = mat[i][j];
        // Move to the next diagonal element
        if (i == j || i + j == mat.length - 1) {
            // Move down on the diagonal
            i++;
            j++;
        } else if (i < j) {
            // Move up on the diagonal
            i++;
        } else if (i > j) {
            // Move left on the diagonal
            j++;
        }
    }

    return diagonal;
}

