        n /= 10;
    }

    for (int i = 0; i < 10; i++) {
        if (digits[i] > 0) {
            smallest = smallest - digits[i] * i;
        }
    }

    return smallest > n ? smallest : -1;
}

public static int findSmallestInteger(int n) {
    // Convert the input integer to a character array
    char[] digits = String.valueOf(n).toCharArray();

    // Sort the digits
    Arrays.sort(digits);

    // Check if the digits are arranged in descending order
    boolean isSorted = true;
    for (int i = 0; i < digits.length - 1; i++) {
        if (digits[i] > digits[i + 1]) {
            isSorted = false;
            break;
        }
    }

    // If the digits are already in descending order, return the original integer
    if (isSorted) {
        return n;
    }

    // Swap the first and the last digit
    char temp = digits[0];
    digits[0] = digits[digits.length - 1];
    digits[digits.length - 1] = temp;

    // Find the smallest integer that can be formed by rearranging the digits
    long smallestInteger = Long.parseLong(String.valueOf(digits));

    // Check if the smallest integer is greater than n
    if (smallestInteger <= n) {
        return -1;
    }

    return (int) smallestInteger;
}

