        for (int j = 1; j <= n; j++) {
            int centerNumber = (int) (Math.pow(10, j) + Math.pow(10, (j - 2)) + (int) (Math.pow(10, (j - 2)) / 10));
            if (String.valueOf(centerNumber).length() < n) {
                continue;
            }
            String number = String.valueOf(centerNumber).substring(0, n);
            if (isSymmetric(number)) {
                result.add(number);
            }
        }
    }
    return result;
}

