}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("Invalid number of points");
    }

    double crossProduct = (points[0][0] - points[2][0]) * (points[0][1] - points[1][1]) - (points[0][1] - points[2][1]) * (points[0][0] - points[1][0]);

    return crossProduct == 0;
}

public static boolean isBoomerang(int[][] points) {
    boolean isBoomerang = false;
    if (points.length == 3) {
        int[] pt1 = points[0];
