        int bc = (pt3[1] - pt2[1]) * (pt1[0] - pt2[0]) - (pt1[1] - pt2[1]) * (pt3[0] - pt2[0]);
        int ca = (pt1[1] - pt3[1]) * (pt2[0] - pt3[0]) - (pt2[1] - pt3[1]) * (pt1[0] - pt3[0]);
        if (ab > 0 && bc > 0 && ca > 0) {
            isBoomerang = true;
        }
    }
