public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        throw new IllegalArgumentException("The points array must be non-null and have length 3.");
    }
    double slope1 = Math.atan2(points[1][1] - points[0][1], points[1][0] - points[0][0]);
    double slope2 = Math.atan2(points[2][1] - points[1][1], points[2][0] - points[1][0]);
    double slope3 = Math.atan2(points[2][1] - points[0][1], points[2][0] - points[0][0]);
    return (slope1 == slope2 && slope2 == slope3);
}

public static boolean isBoomerang(int[][] points) {
    // check if the array is null or empty
    if (points == null || points.length < 3) {
        throw new IllegalArgumentException("Invalid input");
    }

    // sort the points by the x-coordinate
    Arrays.sort(points, Comparator.comparingInt(point -> point[0]));

    // check if the points form a boomerang
    for (int i = 0; i < points.length - 2; i++) {
        int[] point1 = points[i];
        int[] point2 = points[i + 1];
        int[] point3 = points[i + 2];

        // check if the points are collinear
        if (isCollinear(point1, point2, point3)) {
            return false;
        }
    }

    return true;
}

private static boolean isCollinear(int[] point1, int[] point2, int[] point3) {
    // check if the points are the same
    if (point1[0] == point2[0] && point1[1] == point2[1] && point1[0] == point3[0] && point1[1] == point3[1]) {
        return true;
    }

    // check if the points are on the same line
    int determinant = determinant(point1, point2, point3);
    if (determinant == 0) {
        return true;
    }

    return false;
}

private static int determinant(int[] point1, int[] point2, int[] point3) {
    return point1[0] * point2[1] + point1[1] * point3[0] - point1[0] * point3[1] - point1[1] * point2[2] + point3[1] * point2[0];
}

