public static int minPerfectSquareSum(int n) {
    // initialize variables
    int sum = 0;
    int count = 0;
    int currentSquare = 1;

    // loop until the sum is greater than or equal to the target number
    while (sum < n) {
        // calculate the next perfect square
        currentSquare = currentSquare * currentSquare;

        // increment the count if the current square is less than or equal to the target number
        if (currentSquare <= n) {
            count++;
        }

        // add the current square to the sum
        sum += currentSquare;
    }

    // return the count of minimal perfect squares
    return count;
}

public static int minPerfectSquareSum(int n) {
    int count = 0, sum = 0;
    while (sum <= n) {
        sum += Math.pow(count * (count + 1) / 2,2);
        count++;
    }
    return count - 1;
}

public static int minPerfectSquareSum(int n) {

// 1. Initialize a variable to store the minimum number of perfect square numbers
int minPerfectSquareSum = 0;

// 2. Initialize a variable to store the current perfect square number
int currentPerfectSquareNumber = 1;

// 3. While the current perfect square number is less than or equal to the square root of n
while (currentPerfectSquareNumber <= Math.sqrt(n)) {

     // 4. If the current perfect square number is a perfect square number
     if (Math.sqrt(n - currentPerfectSquareNumber*currentPerfectSquareNumber) == Math.floor(Math.sqrt(n - currentPerfectSquareNumber*currentPerfectSquareNumber))) {

          // 5. Increment the minimum number of perfect square numbers
          minPerfectSquareSum++;

     }

     // 6. Increment the current perfect square number
     currentPerfectSquareNumber++;

}

// 7. Return the minimum number of perfect square numbers
return minPerfectSquareSum;

}

