    int count = 0;
    int i = 1;
    while (n > 0) {
        int square = i * i;
        if (square > n) break;
        n -= square;
        count++;
        i++;
    }
    return count;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversed = new StringBuilder();
    for (String word : words) {
        reversed.append(reverse(word));
        reversed.append(" ");
    }
    return reversed.toString().trim();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversedString = new StringBuilder();

    for (int i = 0; i < words.length; i++) {
        StringBuilder word = new StringBuilder(words[i]);
        word.reverse();
        reversedString.append(word);
        if (i < words.length - 1) {
            reversedString.append(" ");
        }
    }

    return reversedString.toString();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    String[] words = s.split(" ");
    StringBuilder reverseWords = new StringBuilder();
    for (String word : words) {
        reverseWords.insert(0, word);
        reverseWords.reverse();
        reverseWords.insert(0, " ");
    }
    reverseWords.deleteCharAt(reverseWords.length() - 1);
    return reverseWords.toString();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String[] reversedWord = new String[words[i].length()];
        for (int j = 0; j < words[i].length(); j++) {
            reversedWord[j] = words[i].charAt(words[i].length() - j - 1);
        }
        result.append(String.join("", reversedWord));
        if (i < words.length - 1) {
            result.append(" ");
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversedString = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        char[] wordChars = word.toCharArray();
        for (int j = wordChars.length - 1; j >= 0; j--) {
            reversedString.append(wordChars[j]);
        }
        if (i != words.length - 1) {
            reversedString.append(" ");
        }
    }
    return reversedString.toString();
}
